// The code exchange proves the challenge that the authorization URL carried.
func TestBhvAuthoauthtwoauthcode008_OAuth2AuthorizationCodeAuthenticator_CodeExchangeProvesTheChallengeOfTheAuthorizationUrl(t *testing.T) {
	t.Parallel()
	client := &recordingTokenClient{responses: []fakeResponse{
		{body: `{"access_token":"tok1","expires_in":3600}`, statusCode: 200},
	}}
	authObj := createAuthCodeAuthenticator()
	authObj.SetApiClient(client)

	challenge, _ := pkceParams(t, authObj.BuildAuthorizationURL(""))
	if err := authObj.ExchangeCode("C"); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	form, err := neturl.ParseQuery(client.requests[0].body)
	if err != nil {
		t.Fatalf("exchange body does not parse: %v", err)
	}
	digest := sha256.Sum256([]byte(form.Get("code_verifier")))
	if want := base64.RawURLEncoding.EncodeToString(digest[:]); challenge != want {
		t.Errorf("expected the exchange to prove challenge %q, the S256 of its verifier is %q", challenge, want)
	}
}

