// A second ExchangeCode really sends its code, even while the first token is
// still valid, and its token replaces the first.
func TestBhvAuthoauthtwoauthcode021_OAuth2AuthorizationCodeAuthenticator_SecondExchangeCodeSendsTheNewCode(t *testing.T) {
	t.Parallel()
	client := &recordingTokenClient{responses: []fakeResponse{
		{body: `{"access_token":"tok1","refresh_token":"ref1","expires_in":3600}`, statusCode: 200},
		{body: `{"access_token":"tok2","refresh_token":"ref2","expires_in":3600}`, statusCode: 200},
	}}
	authObj := createAuthCodeAuthenticator()
	authObj.SetApiClient(client)

	if err := authObj.ExchangeCode("a"); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if err := authObj.ExchangeCode("b"); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if client.requestCount() != 2 {
		t.Fatalf("expected 2 token requests, got %d", client.requestCount())
	}
	if got := client.requests[1].body; !strings.HasPrefix(got, "grant_type=authorization_code&code=b&") {
		t.Errorf("expected the second exchange to send code=b, got %q", got)
	}
	if got := authObj.AuthHeaders()["Authorization"]; got != "Bearer tok2" {
		t.Errorf("expected the second exchange's token, got %q", got)
	}
}

// A second exchange whose response has no refresh_token leaves no refresh
// token behind: the later refresh sends an empty one, not the first session's.
func TestBhvAuthoauthtwoauthcode022_OAuth2AuthorizationCodeAuthenticator_SecondExchangeWithoutRefreshTokenDropsTheOldOne(t *testing.T) {
	t.Parallel()
	client := &recordingTokenClient{responses: []fakeResponse{
		{body: `{"access_token":"tok1","refresh_token":"ref1","expires_in":3600}`, statusCode: 200},
		{body: `{"access_token":"tok2","expires_in":0}`, statusCode: 200},
		{body: `{"access_token":"tok3","expires_in":3600}`, statusCode: 200},
	}}
	authObj := createAuthCodeAuthenticator()
	authObj.SetApiClient(client)

	if err := authObj.ExchangeCode("a"); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if err := authObj.ExchangeCode("b"); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if _, err := authObj.AuthHeadersOrError(); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if got := client.requests[2].body; !strings.HasPrefix(got, "grant_type=refresh_token&refresh_token=&") {
		t.Errorf("expected the refresh to carry no refresh token, got %q", got)
	}
}

// A rejected exchange keeps the previous session, so a mistyped code does not
// log the user out.
func TestBhvAuthoauthtwoauthcode013_OAuth2AuthorizationCodeAuthenticator_FailedExchangeKeepsThePreviousSession(t *testing.T) {
	t.Parallel()
	client := &recordingTokenClient{responses: []fakeResponse{
		{body: `{"access_token":"tok1","refresh_token":"ref1","expires_in":3600}`, statusCode: 200},
		{body: `{"error":"invalid_grant"}`, statusCode: 400},
	}}
	authObj := createAuthCodeAuthenticator()
	authObj.SetApiClient(client)

	if err := authObj.ExchangeCode("a"); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	err := authObj.ExchangeCode("bad")

	var serverErr *apierrors.OAuth2ServerError
	if !errors.As(err, &serverErr) {
		t.Fatalf("expected *OAuth2ServerError, got %T: %v", err, err)
	}
	if got := authObj.AuthHeaders()["Authorization"]; got != "Bearer tok1" {
		t.Errorf("expected the previous token to survive, got %q", got)
	}
}

// F855: InvalidateAccessToken keeps the refresh token and the exchanged state,
// so the next call is a refresh grant rather than ErrAuthCodeNotExchanged.
func TestBhvAuthoauthtwoauthcode016_OAuth2AuthorizationCodeAuthenticator_InvalidateAccessTokenKeepsTheRefreshToken(t *testing.T) {
	t.Parallel()
	client := &recordingTokenClient{responses: []fakeResponse{
		{body: `{"access_token":"tok1","refresh_token":"ref1","expires_in":3600}`, statusCode: 200},
		{body: `{"access_token":"tok2","expires_in":3600}`, statusCode: 200},
	}}
	authObj := createAuthCodeAuthenticator()
	authObj.SetApiClient(client)

	if err := authObj.ExchangeCode("C"); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	authObj.InvalidateAccessToken()
	headers, err := authObj.AuthHeadersOrError()
	if err != nil || headers["Authorization"] != "Bearer tok2" {
		t.Fatalf("expected Bearer tok2 after the invalidation, got %v, %v", headers, err)
	}
	if body := client.requests[1].body; !strings.Contains(body, "grant_type=refresh_token") || !strings.Contains(body, "refresh_token=ref1") {
		t.Errorf("expected a refresh grant with the kept refresh token, got %q", body)
	}
}

